# Workboard

A projects and tasks application using Node.js 22.22.1, ES modules, built-in HTTP and SQLite, and browser HTML/CSS/JavaScript. No package installation or external dependencies are needed.

Run:

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
```

The server binds to `0.0.0.0`. `PORT` defaults to `8080`; `DB_PATH` defaults to `data/workboard.sqlite`. Keep that database file to preserve projects, tasks, and completion state across restarts. Its parent directory is created automatically. Existing project databases receive the task table automatically. `GET /health` returns `{"status":"ok"}`.

Open `http://localhost:8080` to create and open projects. Names are trimmed before saving; empty names display a validation alert. Projects appear in creation order. Forms use standard browser navigation and work without client-side scripting.

Inside a project, create tasks with trimmed titles, mark them complete or open using their checkboxes, and filter by All, Open, or Completed. Each project owns its tasks, displayed in creation order. The filter defaults to All and is stored in the page URL when changed. JavaScript submits checkbox and filter changes automatically; without scripting, explicit save and apply buttons are available.

Verification:

```sh
npm test
node --check server.js
node --check test/projects.test.js
```

The integration tests use temporary SQLite databases to check project and task validation, escaping, ordering, navigation, project isolation, completion changes, and filtering. Server restarts verify persistence of names, IDs, tasks, and both completion states.
import { createServer } from 'node:http';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK(length(trim(name)) > 0)
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK(length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
`);
const listProjects = database.prepare('SELECT id, name FROM projects ORDER BY id');
const findProject = database.prepare('SELECT id, name FROM projects WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const taskFilters = ['All', 'Open', 'Completed'];

function normalizeFilter(value) {
  return taskFilters.includes(value) ? value : 'All';
}

function projectLocation(id, filter) {
  return `/projects/${id}${filter === 'All' ? '' : `?filter=${encodeURIComponent(filter)}`}`;
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #f4f6fa; color: #182334; font: 16px/1.5 system-ui, sans-serif; }
    main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dde3ec; border-radius: 12px; }
    h1 { margin: 0 0 24px; overflow-wrap: anywhere; }
    h2 { margin: 32px 0 12px; font-size: 20px; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    .create { display: flex; gap: 12px; flex-wrap: wrap; }
    input { flex: 1; min-width: 180px; padding: 10px 12px; border: 1px solid #8894a6; border-radius: 6px; font: inherit; }
    input[type="checkbox"] { min-width: auto; width: 20px; height: 20px; margin: 0; cursor: pointer; }
    select { padding: 8px; font: inherit; }
    .task-create { margin-top: 24px; }
    .filter { margin-bottom: 16px; }
    button { padding: 10px 16px; border: 0; border-radius: 6px; background: #2855b5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #1d418e; }
    :focus-visible { outline: 3px solid #e09320; outline-offset: 3px; }
    ul { list-style: none; padding: 0; margin: 0; }
    li { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-top: 1px solid #dde3ec; }
    li span { overflow-wrap: anywhere; min-width: 0; }
    li form { flex-shrink: 0; }
    [role="alert"] { color: #a62222; }
    .empty { color: #5b6675; }
    @media (max-width: 600px) { main { margin: 20px 12px; padding: 24px; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function projectsPage(error = '') {
  const projects = listProjects.all();
  return page('Projects', `
    <h1>Workboard</h1>
    <form method="post" action="/projects">
      <label for="project-name">Project name</label>
      <div class="create"><input id="project-name" name="name" type="text"><button type="submit">Create project</button></div>
    </form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <h2>Projects</h2>
    ${projects.length ? `<ul>${projects.map(project => `
      <li data-testid="project-row"><span>${escapeHtml(project.name)}</span>
        <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
      </li>`).join('')}</ul>` : '<p class="empty">No projects yet.</p>'}`);
}

function projectPage(project, filter = 'All', error = '') {
  const tasks = listTasks.all(project.id).filter(task =>
    filter === 'All' || Boolean(task.completed) === (filter === 'Completed'));
  return page(project.name, `
    <h1>${escapeHtml(project.name)}</h1>
    <form method="get" action="/"><button type="submit">Projects</button></form>
    <form class="task-create" method="post" action="/projects/${project.id}/tasks">
      <input type="hidden" name="filter" value="${filter}">
      <label for="task-title">Task title</label>
      <div class="create"><input id="task-title" name="title" type="text"><button type="submit">Create task</button></div>
    </form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <h2>Tasks</h2>
    <form class="filter" method="get" action="/projects/${project.id}">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${taskFilters.map(option => `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
      <noscript><button type="submit">Apply filter</button></noscript>
    </form>
    ${tasks.length ? `<ul>${tasks.map(task => `
      <li data-testid="task-row"><span>${escapeHtml(task.title)}</span>
        <form method="post" action="/projects/${project.id}/tasks/${task.id}/completion">
          <input type="hidden" name="filter" value="${filter}">
          <input type="checkbox" name="completed" value="1" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''} onchange="this.form.requestSubmit()">
          <noscript><button type="submit">Save completion</button></noscript>
        </form>
      </li>`).join('')}</ul>` : '<p class="empty">No tasks to show.</p>'}`);
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && url.pathname === '/') {
      sendHtml(response, 200, projectsPage());
    } else if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 400, projectsPage('Project name is required'));
        return;
      }
      insertProject.run(name);
      redirect(response, '/');
    } else if (/^\/projects\/[1-9]\d*(?:\/tasks(?:\/[1-9]\d*\/completion)?)?$/.test(url.pathname)) {
      const id = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
      if (!project) {
        sendHtml(response, 404, page('Not found', '<h1>Project not found</h1><a href="/">Projects</a>'));
        return;
      }
      if (request.method === 'GET' && url.pathname === `/projects/${id}`) {
        sendHtml(response, 200, projectPage(project, normalizeFilter(url.searchParams.get('filter'))));
      } else if (request.method === 'POST' && url.pathname === `/projects/${id}/tasks`) {
        const form = await readForm(request);
        const title = (form.get('title') || '').trim();
        const filter = normalizeFilter(form.get('filter'));
        if (!title) {
          sendHtml(response, 400, projectPage(project, filter, 'Task title is required'));
          return;
        }
        insertTask.run(id, title);
        redirect(response, projectLocation(id, filter));
      } else if (request.method === 'POST' && url.pathname.endsWith('/completion')) {
        const taskId = Number(url.pathname.split('/')[4]);
        const form = await readForm(request);
        const result = Number.isSafeInteger(taskId)
          ? updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, id)
          : { changes: 0 };
        if (!result.changes) {
          sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
        redirect(response, projectLocation(id, normalizeFilter(form.get('filter'))));
      } else {
        sendHtml(response, 404, page('Not found', '<h1>Page not found</h1><a href="/">Projects</a>'));
      }
    } else {
      sendHtml(response, 404, page('Not found', '<h1>Page not found</h1><a href="/">Projects</a>'));
    }
  } catch (error) {
    if (!error.status) console.error(error);
    sendHtml(response, error.status || 500, page('Error', `<h1>${error.status === 413 ? 'Request too large' : 'Something went wrong'}</h1>`));
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    database.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

async function launch(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', chunk => { errors += chunk; });
  const base = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${errors}`));
    }, 5000);
    child.once('error', error => { clearTimeout(timer); reject(error); });
    child.once('exit', code => {
      clearTimeout(timer);
      reject(new Error(`Server exited (${code}): ${errors}`));
    });
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) {
        clearTimeout(timer);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    base,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('projects validate, render safely, navigate, and persist across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const databasePath = join(directory, 'nested', 'workboard.sqlite');
  let app;
  try {
    app = await launch(databasePath);
    const health = await fetch(`${app.base}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    let html = await (await fetch(app.base)).text();
    assert.match(html, /<h1>Workboard<\/h1>/);
    assert.match(html, /<label for="project-name">Project name<\/label>/);
    assert.match(html, />Create project<\/button>/);
    assert.doesNotMatch(html, /data-testid="project-row"/);

    const create = name => fetch(`${app.base}/projects`, {
      method: 'POST',
      body: new URLSearchParams({ name }),
      redirect: 'manual',
    });
    for (const name of ['', ' \t\n ']) {
      const invalid = await create(name);
      assert.equal(invalid.status, 400);
      const invalidHtml = await invalid.text();
      assert.match(invalidHtml, /role="alert">Project name is required/);
      assert.doesNotMatch(invalidHtml, /data-testid="project-row"/);
    }
    for (const name of ['  First project  ', '<script>alert("x")</script>']) {
      const response = await create(name);
      assert.equal(response.status, 303);
      assert.equal(response.headers.get('location'), '/');
    }
    html = await (await fetch(app.base)).text();
    assert.equal((html.match(/data-testid="project-row"/g) || []).length, 2);
    assert.match(html, /<span>First project<\/span>/);
    assert.match(html, /&lt;script&gt;alert\(&quot;x&quot;\)&lt;\/script&gt;/);
    assert.doesNotMatch(html, /<script>/);
    assert.ok(html.indexOf('First project') < html.indexOf('&lt;script&gt;'));
    const projectPaths = [...html.matchAll(/action="(\/projects\/\d+)"/g)].map(match => match[1]);
    assert.equal(projectPaths.length, 2);
    const detail = await (await fetch(`${app.base}${projectPaths[0]}`)).text();
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /action="\/"/);
    assert.match(detail, />Projects<\/button>/);
    assert.equal((await fetch(`${app.base}/projects/999`)).status, 404);

    await app.stop();
    app = undefined;
    app = await launch(databasePath);
    const persisted = await (await fetch(app.base)).text();
    assert.equal(persisted, html);
    const persistedDetail = await fetch(`${app.base}${projectPaths[0]}`);
    assert.equal(persistedDetail.status, 200);
    assert.match(await persistedDetail.text(), /<h1>First project<\/h1>/);
  } finally {
    if (app) await app.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('tasks validate, filter, remain project-owned, and save completion across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-test-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let app;
  try {
    // Start with the Task 001 schema to verify a compatible database upgrade.
    const existingDatabase = new DatabaseSync(databasePath);
    try {
      existingDatabase.exec(`
        CREATE TABLE projects (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          name TEXT NOT NULL CHECK(length(trim(name)) > 0)
        );
        INSERT INTO projects (name) VALUES ('One');
      `);
    } finally {
      existingDatabase.close();
    }
    app = await launch(databasePath);
    const post = (path, values) => fetch(`${app.base}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    const getPage = async path => (await fetch(`${app.base}${path}`)).text();
    const rows = html => [...html.matchAll(/<li data-testid="task-row">[\s\S]*?<\/li>/g)].map(match => match[0]);

    await post('/projects', { name: 'Two' });
    let html = await getPage('/projects/1');
    assert.match(html, /<h1>One<\/h1>/);
    assert.match(html, /<label for="task-title">Task title<\/label>/);
    assert.match(html, />Create task<\/button>/);
    assert.match(html, /<label for="task-filter">Task filter<\/label>/);
    assert.match(html, /<option selected>All<\/option>/);
    assert.match(html, /<option>Open<\/option>/);
    assert.match(html, /<option>Completed<\/option>/);
    assert.equal(rows(html).length, 0);

    for (const title of ['', ' \t\n ']) {
      const response = await post('/projects/1/tasks', { title });
      assert.equal(response.status, 400);
      html = await response.text();
      assert.match(html, /role="alert">Task title is required/);
      assert.equal(rows(html).length, 0);
    }
    for (const title of ['  First task  ', '<script>"second"</script>']) {
      const response = await post('/projects/1/tasks', { title });
      assert.equal(response.status, 303);
      assert.equal(response.headers.get('location'), '/projects/1');
    }
    await post('/projects/2/tasks', { title: 'Other project task' });
    html = await getPage('/projects/1');
    const taskRows = rows(html);
    assert.equal(taskRows.length, 2);
    assert.match(taskRows[0], /<span>First task<\/span>/);
    assert.match(taskRows[0], /type="checkbox".*aria-label="Complete First task"/);
    assert.match(taskRows[1], /&lt;script&gt;&quot;second&quot;&lt;\/script&gt;/);
    assert.doesNotMatch(html, /<script>/);
    assert.doesNotMatch(taskRows.join(''), / checked/);
    assert.doesNotMatch(html, /Other project task/);
    assert.equal(rows(await getPage('/projects/1?filter=Open')).length, 2);
    assert.equal(rows(await getPage('/projects/1?filter=Completed')).length, 0);

    const completionPath = taskRows[0].match(/action="([^"]+\/completion)"/)[1];
    const completed = await post(completionPath, { completed: '1', filter: 'Open' });
    assert.equal(completed.status, 303);
    assert.equal(completed.headers.get('location'), '/projects/1?filter=Open');
    const completedPage = await getPage('/projects/1?filter=Completed');
    assert.equal(rows(completedPage).length, 1);
    assert.match(rows(completedPage)[0], / checked/);
    assert.match(completedPage, /<option selected>Completed<\/option>/);
    const openRows = rows(await getPage('/projects/1?filter=Open'));
    assert.equal(openRows.length, 1);
    assert.match(openRows[0], /second/);
    const invalid = await post('/projects/1/tasks', { title: '   ' });
    assert.equal(rows(await invalid.text()).length, 2);

    const crossProject = await post(completionPath.replace('/projects/1/', '/projects/2/'), {});
    assert.equal(crossProject.status, 404);
    assert.equal((await post('/projects/999/tasks', { title: 'Orphan' })).status, 404);
    assert.equal((await post('/projects/1/tasks/999/completion', {})).status, 404);
    const otherPage = await getPage('/projects/2');
    assert.equal(rows(otherPage).length, 1);
    assert.match(otherPage, /Other project task/);
    assert.doesNotMatch(rows(otherPage)[0], / checked/);
    assert.match(await getPage('/projects/1?filter=invalid'), /<option selected>All<\/option>/);

    const savedPage = await getPage('/projects/1');
    await app.stop();
    app = undefined;
    app = await launch(databasePath);
    assert.equal(await getPage('/projects/1'), savedPage);
    assert.equal(await getPage('/projects/1?filter=Completed'), completedPage);
    assert.equal(await getPage('/projects/2'), otherPage);

    assert.equal((await post(completionPath, {})).status, 303);
    html = await getPage('/projects/1');
    assert.equal(rows(html).length, 2);
    assert.doesNotMatch(rows(html).join(''), / checked/);
    assert.equal(rows(await getPage('/projects/1?filter=Completed')).length, 0);
    await app.stop();
    app = undefined;
    app = await launch(databasePath);
    assert.equal(await getPage('/projects/1'), html);
  } finally {
    if (app) await app.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

